"nodes": [
  {
    "id": "classifyUrgency1",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": { "label": "Classify Urgency" },
    "inputs": {
      "script": "var subject = ($vars.emailReceived1.output.subject || '').toLowerCase();\nvar body = ($vars.emailReceived1.output.bodyPreview || '').toLowerCase();\nvar urgentKeywords = ['urgent', 'critical', 'asap', 'emergency', 'escalate', 'outage', 'down', 'incident', 'p0', 'p1', 'blocker', 'immediate', 'high priority', 'sla'];\nvar isUrgent = urgentKeywords.some(function(kw) { return subject.indexOf(kw) !== -1 || body.indexOf(kw) !== -1; });\nreturn { isUrgent: isUrgent };"
    }
  },
  {
    "id": "classifyVip1",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": { "label": "Classify VIP" },
    "inputs": {
      "script": "var senderAddress = '';\nif ($vars.emailReceived1.output.from && $vars.emailReceived1.output.from.emailAddress) {\n  senderAddress = ($vars.emailReceived1.output.from.emailAddress.address || '').toLowerCase();\n}\nif (!senderAddress && $vars.emailReceived1.output.sender && $vars.emailReceived1.output.sender.emailAddress) {\n  senderAddress = ($vars.emailReceived1.output.sender.emailAddress.address || '').toLowerCase();\n}\nvar vipDomains = ['acme-corp.com', 'enterprise.com', 'vip-client.com', 'bigclient.com', 'fortune500.com', 'uipath.com'];\nvar atIdx = senderAddress.indexOf('@');\nvar senderDomain = atIdx !== -1 ? senderAddress.substring(atIdx + 1) : '';\nvar isVip = vipDomains.indexOf(senderDomain) !== -1;\nreturn { isVip: isVip, senderEmail: senderAddress, senderDomain: senderDomain };"
    }
  },
  {
    "id": "routeEscalation1",
    "type": "core.logic.decision",
    "typeVersion": "1.1",
    "display": { "label": "Urgent AND VIP?" },
    "inputs": {
      "expression": "$vars.classifyUrgency1.output.isUrgent === true && $vars.classifyVip1.output.isVip === true",
      "trueLabel": "High Touch",
      "falseLabel": "Standard"
    }
  },
  {
    "id": "generateTicket1",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": { "label": "Generate Support Ticket" },
    "inputs": {
      "script": "var emailId = $vars.emailReceived1.output.id || 'UNKNOWN';\nvar shortId = emailId.replace(/[^A-Za-z0-9]/g, '').substring(0, 8).toUpperCase();\nif (shortId.length < 4) { shortId = 'SUPPORT'; }\nvar ticketId = 'TKT-' + shortId;\nvar senderEmail = $vars.classifyVip1.output.senderEmail || 'unknown';\nvar subject = $vars.emailReceived1.output.subject || 'No subject';\nvar isUrgent = $vars.classifyUrgency1.output.isUrgent || false;\nvar priority = isUrgent ? 'High' : 'Normal';\nvar replyBody = 'Thank you for contacting us. Your support ticket has been created.\\n\\nTicket ID: ' + ticketId + '\\nPriority: ' + priority + '\\nStatus: Open\\nSubject: ' + subject + '\\n\\nA member of our team will respond within 4 business hours (High priority) or 24 business hours (Normal priority).\\n\\nThank you for your patience.';\nreturn { ticketId: ticketId, priority: priority, senderEmail: senderEmail, replyBody: replyBody };"
    }
  },
  {
    "id": "endHighTouch",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": { "label": "End High Touch" }
  },
  {
    "id": "endStandard",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": { "label": "End Standard" }
  },
  {
